    "t": "小脳の役割は、運動の協調・調整と運動学習。正答として扱われたのは、運動をスムーズにする役割（56-pm-23）、運動学習の過程に小脳が関与する（60-pm-74）、記憶に基づく運動の修飾（53-am-82）、運動制御における内部モデル形成の中枢（59-pm-23）。小脳は随意運動に関与する側で、49-am-64の「随意運動に関与しないもの」の正答は視床下部。出典で確かめられたのは、運動指令と感覚の比較、誤差の修正、運動学習、フィードフォワード制御まで。「内部モデル」の語そのものは今回の出典に記載がなく、確認できていない。UTHealthは大脳小脳が運動の「企画とタイミング」に関わるとも記すが、53-am-82では「一連の動作の企画」「自発的な行為のプログラミング」が誤りの選択肢だった。UTHealthも、運動の指令は小脳で始まるのではなく、小脳は下行する運動指令を修正する、と記す。61-am-39では、外的刺激の情報を反映した運動の準備は運動前野が正答で、小脳は誤りの選択肢。",
