    "t": "前頭前野の損傷では、行動を抑える（ノーゴー反応）ことや、分類基準が変わったときに切り替える（ウィスコンシン・カード分類課題で前の基準に固執する）ことが難しくなる。一般に健忘症のような記憶障害は生じないが、将来の予定の記憶や、出来事の順序の記憶は障害される。",
