  "figures": [
   {
    "src": "/organs/limbic-system.svg",
    "alt": "大脳半球を内側から見た模式図。画像の左が前、右が後ろ。前頭葉（青）、頭頂葉（黄）、後頭葉（桃）、側頭葉（緑）に色分けし、脳梁を囲むように帯状回と海馬傍回からなる紫の帯（辺縁葉）がC字に走る。脳梁の下を脳弓が弓なりに走り、前方で下って乳頭体に終わる。視床は脳弓に囲まれる位置、海馬は側頭葉の内側の深部、扁桃体は側頭葉の先端の深部に点線で示す。後方には頭頂後頭溝と鳥距溝があり、鳥距溝のまわりが一次視覚野（有線領）。",
    "caption": "大脳半球を内側から見た（正中矢状断の）模式図。位置関係を示すもので、大きさ・形は実物と異なります。海馬・扁桃体・視床は深部の構造で、位置の目安として描いています。左右どちらの半球でも並びは同じです。"
   },
   {
    "src": "/organs/limbic-system-2.svg",
    "alt": "Papez回路の模式図。海馬から脳弓を通って乳頭体へ、乳頭体視床路で視床前核へ、視床前核から帯状回（ブロードマン24野）へ、帯状回から海馬へ戻る、四つの箱が矢印でつながる閉じた回路。",
    "caption": "Papez回路の模式図。箱は構造、矢印は信号の流れの向きを示します。経路の途中にある中継や、他の構造との連絡は省略しています。"
   }
  ],
