    "t": "視床下部は、交感神経・副交感神経の機能と内分泌を統合して調節する中枢で、体の恒常性の維持に重要な役割をもつ。中脳以下の自律機能の中枢が呼吸・循環・発汗などの個別の自律機能を調節するのに対し、視床下部はそれらを統合して調節する。",
