    "src": "/organs/brainstem-4.svg",
    "alt": "脳幹の高さ別の脳神経核の一覧。中脳：動眼神経核、滑車神経核、動眼神経副核（自律性）、三叉神経中脳路核。橋：外転神経核、三叉神経運動核、顔面神経核、三叉神経主知覚核、前庭神経核、蝸牛神経核。延髄：舌下神経核、疑核、迷走神経背側運動核（自律性）、孤束核、三叉神経脊髄路核。",
    "caption": "脳幹の高さ別の脳神経核の一覧。核の性質（眼・舌を動かす／咀嚼・表情・咽頭喉頭を動かす／自律性／感覚）で色分けしています。三叉神経中脳路核は橋の高さから中脳まで、三叉神経脊髄路核は延髄から第2頸髄まで伸びます。上唾液核・下唾液核は、明瞭な細胞集団を作らず網様体の中に散らばるため描いていません。前庭神経核・蝸牛神経核は、北大の資料に従い橋に置いていますが、前庭神経核は標準神経病学が延髄の構造に挙げており、出典により高さの扱いが異なります。"
