    "t": "脈絡叢は、血管に富む構造で、脳室に面する表面は上衣の細胞の層で覆われる。北大の資料は「側脳室・第三脳室・第四脳室の3つの脳室」にあるとし、OpenStaxは側脳室を左右2つと数えて「4つの脳室すべて」にあるとする（脳室の数え方の違いとみられる）。",
