  "summary": {
   "t": "後頭葉は頭頂後頭溝より後ろにあり、内側面の鳥距溝をはさむ上下の脳回（有線領）に一次視覚野がある。視覚情報は一次視覚野に入り、周囲の視覚連合野を経て、側頭葉へ向かう腹側経路（何）と頭頂葉へ向かう背側経路（どこ・どう）に分かれて処理される。一次視覚野の障害で同名半盲や皮質盲が起こる。",
   "s": [
    1,
    2,
    3,
    4,
    5
   ]
  },
  "location": [
   {
    "t": "後頭葉は頭頂後頭溝の後部にあり、先端部を後頭極という。外側面では、頭頂葉との間にはっきりした脳溝がない。",
    "s": [
     1,
     6
    ]
   },
   {
    "t": "一次視覚野は、主に半球の内側面（大脳縦裂に面する壁）にある。",
    "s": [
     2
    ]
   }
  ],
  "structure": [
   {
    "t": "鳥距溝をはさむ上下の脳回は有線領とよばれ、ここに一次視覚野（V1）がある。",
    "s": [
     1
    ]
   },
   {
    "t": "一次視覚野の周囲にV2・V3があり、これらが視覚連合野にあたる。一次視覚野の網膜部位局在（網膜の位置と対応する並び）では、網膜の中心視野に対応する領域が広い。",
    "s": [
     2,
     1
    ]
   },
   {
    "t": "視覚の経路は、視交叉から視索を経て、視床の外側膝状体に達し、外側膝状体から後頭葉の視覚野へ投射する。",
    "s": [
     2
    ]
   }
  ],
  "function": [
   {
    "t": "一次視覚野は、大脳皮質で視覚情報が最初に入ってくる領域。基本的な形や物体の輪郭が認識され始め、左右の眼からの入力が比較されて奥行きの情報が取り出される。左右の半球は、それぞれ反対側の視野の半分を処理する。",
    "s": [
     4,
     2
    ]
   },
   {
    "t": "視覚連合野（V2・V3）は、色や動きの情報を加えて、より複雑な視覚を作る。その情報は、側頭葉と頭頂葉へ送られる。",
    "s": [
     2
    ]
   },
   {
    "t": "視覚処理は、側頭葉へ向かう腹側経路と、頭頂葉へ向かう背側経路に分かれる。腹側経路は視覚刺激が何かを同定し（what）、背側経路は物体の位置を捉えて体の動きを導く（where／how）。",
    "s": [
     2,
     3
    ]
   }
  ],
  "mechanism": [
   {
    "t": "一次視覚野が損傷されると、反対側の視野が両眼とも見えなくなる。たとえば左側のV1全体の損傷では、左右の眼とも右半分の視野が見えなくなり、これを同名半盲とよぶ。",
    "s": [
     4
    ]
   },
   {
    "t": "一次視覚野の病変で皮質盲が生じる。その一型であるAnton症候群では、見えていないのに自身の障害を認識せず、見えている物を作話で説明する。後頭葉に関わるてんかん発作では、反対側の視野に色のついた線や網目などの幻視が起こることがある。",
    "s": [
     5
    ]
   },
   {
    "t": "同名半盲は、頭部や視線を動かせば代償できるため、半側空間無視とは独立した障害とされる。",
    "s": [
     7
    ]
   },
   {
    "t": "視覚失認は、後大脳動脈の支配領域との関連が深い。統覚型視覚失認では、両側の有線野を含む後頭葉の損傷例が報告されている。",
    "s": [
     8
    ]
   },
   {
    "t": "レビー小体型認知症では、一次視覚野を含む後頭葉の代謝・血流の低下が特徴的で、アルツハイマー病との鑑別に有用とされる。",
    "s": [
     9
    ]
   }
  ],
