   {
    "t": "病態失認（片麻痺の無認知）は、右半球損傷・左片麻痺で起こりやすく、非優位側の縁上回、または視床と頭頂葉をつなぐ線維の損傷で生じる可能性が指摘されている。",
    "s": [
     5
    ]
   }
