    "t": "随意運動の指令は、中心前回（一次運動野）から、内包・大脳脚・延髄の錐体を通る皮質脊髄路で下りる。皮質脊髄路に含まれるものとして、大脳脚は正解、中心後回（感覚野）は誤りの選択肢だった。「随意運動に関与しないもの」を選ぶ問題では、視床下部が正解で、中心前回・内包・大脳脚は随意運動に関与する側だった。",
