    "t": "視床は、大脳皮質と、末梢・脊髄・脳幹のあいだで情報を中継する。嗅覚を除くすべての感覚は、大脳皮質で処理される前に視床でシナプスを換える。視床は情報を通すだけでなく処理もし、たとえば視覚を受ける部分は、どの視覚刺激が重要か（注意）に影響する。",
