    "t": "失語の型の組合せ: ブローカ失語は非流暢、ウェルニッケ失語は流暢で理解が不良（「流暢・良好」は誤り）、健忘失語と伝導失語は流暢、超皮質性運動失語はブローカ失語に似て非流暢。",
